/**
 * Generate acr.tf with Azure Container Registry
 */

import type { AzureInfraConfig } from '../../types/config.ts';
import { buildAzureTerraformName } from '../../utils/azure/build-azure-terraform-name.ts';

export function generateAcrTf(config: AzureInfraConfig): string {
  const name = buildAzureTerraformName(
    config,
    'containerRegistry',
    '"${replace(var.project_name, "-", "")}${var.environment}acr"',
  );

  return `# Azure Container Registry
# Generated by: npx tsdevstack infra:generate

resource "azurerm_container_registry" "main" {
  name                = ${name}
  resource_group_name = data.azurerm_resource_group.main.name
  location            = data.azurerm_resource_group.main.location
  sku                 = "Basic"
  admin_enabled       = false
  tags                = local.tags
}
`;
}
